import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds exact half-cent ties to the even cent so totals are not biased upward", () => {
    expect(roundCents(1.5)).toBe(2);
    expect(roundCents(2.5)).toBe(2);
    expect(roundCents(1234.5)).toBe(1234);
    expect(roundCents(1235.5)).toBe(1236);
  });

  it("rounds non-tie fractions to the nearest cent", () => {
    expect(roundCents(10.49)).toBe(10);
    expect(roundCents(10.51)).toBe(11);
    expect(roundCents(7)).toBe(7);
  });

  it("treats refunds (negative amounts) symmetrically with charges", () => {
    expect(roundCents(-2.5)).toBe(-2);
    expect(roundCents(-3.5)).toBe(-4);
    expect(roundCents(-10.51)).toBe(-11);
    expect(roundCents(-0.5) + 0).toBe(0);
  });
});

